import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

l1_norm_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Kernel to compute the row-wise sum of absolute values
__global__ void rowwise_abs_sum_kernel(const float* __restrict__ x,
                                       float* __restrict__ row_sum,
                                       int N, int D) {
    // Each block handles one row, each thread accumulates partial sums
    int row = blockIdx.x;
    if (row >= N) return;

    float sum_val = 0.0f;
    int start = row * D;
    for(int col = threadIdx.x; col < D; col += blockDim.x) {
        sum_val += fabsf(x[start + col]);
    }

    // Use shared memory to reduce partial sums within the block
    __shared__ float sdata[1024]; // Adjust blockDim if needed
    sdata[threadIdx.x] = sum_val;
    __syncthreads();

    // Parallel reduction within block
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // Write the final sum to row_sum
    if (threadIdx.x == 0) {
        row_sum[row] = sdata[0];
    }
}

// Kernel to divide each element by its row's L1 norm
__global__ void rowwise_div_kernel(const float* __restrict__ x,
                                   const float* __restrict__ row_sum,
                                   float* __restrict__ out,
                                   int N, int D) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * D) return;

    int row = idx / D;
    out[idx] = x[idx] / row_sum[row];
}

// Custom CUDA function that computes L1 norm row-wise: x / sum(abs(x))
torch::Tensor l1_norm_cuda(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Input tensor must be 2D [N, D].");
    auto N = x.size(0);
    auto D = x.size(1);

    // Allocate output tensor
    auto out = torch::empty_like(x);

    // Allocate space for row-wise sums
    auto row_sum = torch::zeros({N}, x.options());

    // Run rowwise_abs_sum_kernel
    const int threads = 1024;
    const dim3 blocks_sum(N);
    rowwise_abs_sum_kernel<<<blocks_sum, threads>>>(x.data_ptr<float>(),
                                                    row_sum.data_ptr<float>(),
                                                    N, D);

    // Run rowwise_div_kernel
    const int total_elements = N * D;
    const int threads_div = 1024;
    const int blocks_div = (total_elements + threads_div - 1) / threads_div;
    rowwise_div_kernel<<<blocks_div, threads_div>>>(x.data_ptr<float>(),
                                                    row_sum.data_ptr<float>(),
                                                    out.data_ptr<float>(),
                                                    N, D);

    return out;
}
"""

l1_norm_cpp = "torch::Tensor l1_norm_cuda(torch::Tensor x);"

# Build the extension
l1_norm_ext = load_inline(
    name="l1_norm_ext",
    cpp_sources=l1_norm_cpp,
    cuda_sources=l1_norm_src,
    functions=["l1_norm_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA L1 normalization.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.l1_norm = l1_norm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.l1_norm.l1_norm_cuda(x)
